{
    var dataPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "tickets.csv");
    var modelOutputPath = Path.Combine(builder.Environment.ContentRootPath, "Data", "model.zip");

    using var loggerFactory = LoggerFactory.Create(b => b.AddConsole());
    var logger = loggerFactory.CreateLogger<ModelTrainingService>();

    var trainer = new ModelTrainingService(builder.Environment, logger);
    var (metrics, savedPath) = trainer.TrainAndEvaluate();

    logger.LogInformation(
        "Startup training complete — Macro: {Macro:F4}, Micro: {Micro:F4}",
        metrics.MacroAccuracy, metrics.MicroAccuracy);

    return savedPath;
}

